import type {ReactNode} from 'react';
import React from 'react';

import type {ButtonSize, SelectOption} from '@gravity-ui/uikit';
import {Text} from '@gravity-ui/uikit';

import {QueueIcon} from '~/src/components/QueueIcon/QueueIcon';

import {cnQueueSelect} from '../QueueSelect.classname';
import {iconSizeByButtonSize} from '../constants';
import type {QueueInfo} from '../types';

export const renderDisplayValue = (
    valueOptions: SelectOption<QueueInfo>[],
    withValueIcon = false,
    placeholder: ReactNode = '',
    buttonSize: ButtonSize = 'm',
) => {
    const queue = valueOptions[0]?.data;
    const queueId = queue?.key || '';
    const iconSize = iconSizeByButtonSize[buttonSize];

    if (valueOptions.length === 0) {
        return placeholder || '—';
    }

    return (
        <div className={cnQueueSelect('select-item', {forControl: true, size: buttonSize})}>
            {withValueIcon && (
                <QueueIcon
                    queueId={queueId}
                    className={cnQueueSelect('select-item-icon')}
                    size={iconSize}
                />
            )}
            <Text className={cnQueueSelect('select-value-name')} variant="body-1" color="primary">
                {queueId}: {queue?.display ?? queueId}
            </Text>
        </div>
    );
};
